        for i, ch in enumerate(line):
            if ch == "'" and not in_dquote: in_squote = not in_squote
            elif ch == '"' and not in_squote: in_dquote = not in_dquote
            elif ch == '#' and not in_squote and not in_dquote:
                comment_idx = i
                break
        if comment_idx != -1:
            line = line[:comment_idx]
        lines.append(line)

    # Check if JSON
    trimmed = text.strip()
    if (trimmed.startswith('{') and trimmed.endswith('}')) or (trimmed.startswith('[') and trimmed.endswith(']')):
        try:
            return json.loads(trimmed)
        except Exception:
            pass

    # Indent-based block parser
    def parse_block(line_indices, base_indent=0):
        if not line_indices:
            return None

        # Check if sequence or map
        first_line = lines[line_indices[0]]
        content = first_line.lstrip()
        indent = len(first_line) - len(content)

        is_seq = content.startswith('- ') or content == '-'

        if is_seq:
            result = []
            cur_item_lines = []
            for idx in line_indices:
                line = lines[idx]
                if not line.strip(): continue
                cur_indent = len(line) - len(line.lstrip())
                if cur_indent == indent and (line.lstrip().startswith('- ') or line.lstrip() == '-'):
                    if cur_item_lines:
                        result.append(parse_item(cur_item_lines, indent))
                    cur_item_lines = [idx]
                else:
                    cur_item_lines.append(idx)
            if cur_item_lines:
                result.append(parse_item(cur_item_lines, indent))
            return result
        else:
            result = {}
            cur_key = None
            cur_lines = []
            for idx in line_indices:
                line = lines[idx]
                if not line.strip(): continue
                cur_indent = len(line) - len(line.lstrip())
                if cur_indent == indent and ':' in line.lstrip():
                    if cur_key is not None:
                        result[cur_key] = parse_val(cur_lines, indent)
                    k, _, v = line.lstrip().partition(':')
                    cur_key = parse_scalar(k.strip())
                    v_str = v.strip()
                    if v_str:
                        cur_lines = [(idx, v_str)]
                    else:
                        cur_lines = []
                else:
                    cur_lines.append(idx)
            if cur_key is not None:
                result[cur_key] = parse_val(cur_lines, indent)
            return result

    def parse_item(item_lines, parent_indent):
        first_idx = item_lines[0]
        first_line = lines[first_idx]
        content = first_line.lstrip()
        after_dash = content[1:].lstrip()

        if not after_dash: # '-' with sub-block on next lines
            sub_indices = item_lines[1:]
            if not sub_indices: return None
            return parse_block(sub_indices)
        elif ':' in after_dash and not (after_dash.startswith('{') or after_dash.startswith('[')):
            # inline map start
            # rewrite line as indent spaces + after_dash
            indent = len(first_line) - len(content) + 2
            lines[first_idx] = ' ' * indent + after_dash
            return parse_block(item_lines)
        else:
            return parse_scalar(after_dash)

    def parse_val(val_lines, parent_indent):
        if not val_lines: return None
        if isinstance(val_lines[0], tuple): # (idx, val_str)
            first_str = val_lines[0][1]
            rest_indices = val_lines[1:]
            if rest_indices:
                return parse_block(rest_indices)
            else:
                return parse_scalar(first_str)
        else:
            return parse_block(val_lines)

    def parse_scalar(s):
        s = s.strip()
        if not s: return None
        if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
            return s[1:-1]
        if s.lower() == 'true': return True
        if s.lower() == 'false': return False
        if s.lower() in ('null', '~'): return None
        try:
            if '.' in s or 'e' in s.lower():
                return float(s)
            return int(s)
        except ValueError:
            pass
        if (s.startswith('[') and s.endswith(']')) or (s.startswith('{') and s.endswith('}')):
            try: return json.loads(s)
            except: pass
        return s

    non_empty_indices = [i for i, l in enumerate(lines) if l.strip()]
    if not non_empty_indices: return None
    return parse_block(non_empty_indices)

