        r_vals = self.right.eval(val, ctx)
        res = []
        for lv in l_vals:
            for rv in r_vals:
                if self.op == '+':
                    if isinstance(lv, list) and isinstance(rv, list): res.append(lv + rv)
                    elif isinstance(lv, dict) and isinstance(rv, dict):
                        d = dict(lv); d.update(rv); res.append(d)
                    elif isinstance(lv, (int, float)) and isinstance(rv, (int, float)): res.append(lv + rv)
                    elif isinstance(lv, str) and isinstance(rv, str): res.append(lv + rv)
                    else: res.append(None)
                elif self.op == '*':
                    if isinstance(lv, dict) and isinstance(rv, dict):
                        def deep_merge(a, b):
                            res_m = dict(a)
                            for k, v in b.items():
                                if k in res_m and isinstance(res_m[k], dict) and isinstance(v, dict):
