import sys, os, re, json

class Token:
    def __init__(self, kind, value, pos=0):
        self.kind = kind
        self.value = value
        self.pos = pos

def tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch.isspace():
            i += 1
            continue
        if ch in ('"', "'"):
            quote = ch
            j = i + 1
            val = []
            while j < n and s[j] != quote:
                if s[j] == '\\' and j + 1 < n:
                    val.append(s[j+1])
                    j += 2
                else:
                    val.append(s[j])
                    j += 1
            if j < n: j += 1
            tokens.append(Token('STRING', ''.join(val), i))
            i = j
            continue
        if i + 1 < n:
            two = s[i:i+2]
            if two in ('==', '!=', '<=', '>=', '+=', '-=', '*=', '|=', '..'):
                tokens.append(Token(two, two, i))
                i += 2
                continue
        if ch in ('.', ',', '|', '=', '<', '>', '+', '-', '*', '/', '%', ':', '(', ')', '[', ']', '{', '}', ';'):
            tokens.append(Token(ch, ch, i))
            i += 1
            continue
        if ch == '$':
            j = i + 1
            while j < n and (s[j].isalnum() or s[j] == '_'):
                j += 1
            tokens.append(Token('VAR', s[i:j], i))
            i = j
            continue
        if ch.isdigit():
            j = i
            while j < n and (s[j].isdigit() or s[j] == '.'):
                j += 1
            num_str = s[i:j]
            val = float(num_str) if '.' in num_str else int(num_str)
            tokens.append(Token('NUMBER', val, i))
            i = j
            continue
        if ch.isalpha() or ch == '_':
            j = i
            while j < n and (s[j].isalnum() or s[j] in ('_', '-')):
                j += 1
            word = s[i:j]
            if word in ('and', 'or', 'not', 'as', 'true', 'false', 'null'):
                tokens.append(Token(word.upper(), word, i))
            else:
                tokens.append(Token('IDENT', word, i))
            i = j
            continue
        tokens.append(Token('CHAR', ch, i))
        i += 1
    tokens.append(Token('EOF', '', n))
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos]

    def consume(self, kind=None):
        tok = self.peek()
        if kind and tok.kind != kind and tok.value != kind:
            raise SyntaxError(f"Expected {kind}, got {tok.kind} ({tok.value}) at pos {tok.pos}")
        self.pos += 1
        return tok

    def parse(self):
        if self.peek().kind == 'EOF':
            return DotNode()
        res = self.parse_comma()
        return res

    def parse_comma(self):
        node = self.parse_pipe()
        while self.peek().kind == ',':
            self.consume(',')
            right = self.parse_pipe()
            node = CommaNode(node, right)
        return node

    def parse_pipe(self):
        node = self.parse_assign()
        while self.peek().kind == '|':
            self.consume('|')
            right = self.parse_assign()
            node = PipeNode(node, right)
        return node

    def parse_assign(self):
        node = self.parse_as()
        tok = self.peek()
        if tok.kind in ('=', '+=', '-=', '*=', '|='):
            op = tok.kind
            self.consume()
            right = self.parse_assign()
            return AssignNode(node, op, right)
        return node

    def parse_as(self):
        node = self.parse_or()
        if self.peek().kind == 'AS':
            self.consume('AS')
            var_tok = self.consume('VAR')
            right = self.parse_assign()
            return AsNode(node, var_tok.value, right)
        return node

    def parse_or(self):
        node = self.parse_and()
        while self.peek().kind == 'OR':
            self.consume('OR')
            right = self.parse_and()
            node = BinaryOpNode(node, 'or', right)
        return node

    def parse_and(self):
        node = self.parse_eq()
        while self.peek().kind == 'AND':
            self.consume('AND')
            right = self.parse_eq()
            node = BinaryOpNode(node, 'and', right)
        return node

    def parse_eq(self):
        node = self.parse_rel()
        while self.peek().kind in ('==', '!='):
            op = self.consume().kind
            right = self.parse_rel()
            node = BinaryOpNode(node, op, right)
        return node

    def parse_rel(self):
        node = self.parse_add()
        while self.peek().kind in ('<', '>', '<=', '>='):
            op = self.consume().kind
            right = self.parse_add()
            node = BinaryOpNode(node, op, right)
        return node

    def parse_add(self):
        node = self.parse_mul()
        while self.peek().kind in ('+', '-'):
            op = self.consume().kind
            right = self.parse_mul()
            node = BinaryOpNode(node, op, right)
        return node

    def parse_mul(self):
        node = self.parse_postfix()
        while self.peek().kind in ('*', '/', '%'):
            op = self.consume().kind
            right = self.parse_postfix()
            node = BinaryOpNode(node, op, right)
        return node

    def parse_postfix(self):
        node = self.parse_primary()
        while True:
            tok = self.peek()
            if tok.kind == '.':
                self.consume('.')
                next_tok = self.peek()
                if next_tok.kind == 'IDENT':
                    key = self.consume().value
                    node = PathAccessNode(node, key)
                elif next_tok.kind == 'STRING':
                    key = self.consume().value
                    node = PathAccessNode(node, key)
                elif next_tok.kind == '[':
                    # e.g. .[] or .[0]
                    pass
                else:
                    break
            elif tok.kind == '[':
                self.consume('[')
                if self.peek().kind == ']':
                    self.consume(']')
                    node = ArrayIterNode(node)
                else:
                    idx_expr = self.parse_comma()
                    self.consume(']')
                    node = ArrayIndexNode(node, idx_expr)
            else:
                break
        return node

    def parse_primary(self):
        tok = self.peek()
        if tok.kind == '.':
            self.consume('.')
            next_tok = self.peek()
            if next_tok.kind == 'IDENT':
                key = self.consume().value
                node = PathAccessNode(DotNode(), key)
            elif next_tok.kind == 'STRING':
                key = self.consume().value
                node = PathAccessNode(DotNode(), key)
            elif next_tok.kind == '[':
                self.consume('[')
                if self.peek().kind == ']':
                    self.consume(']')
                    node = ArrayIterNode(DotNode())
                else:
                    idx_expr = self.parse_comma()
                    self.consume(']')
                    node = ArrayIndexNode(DotNode(), idx_expr)
            else:
                node = DotNode()
            return node
        elif tok.kind == 'NUMBER':
            return LiteralNode(self.consume().value)
        elif tok.kind == 'STRING':
            return LiteralNode(self.consume().value)
        elif tok.kind in ('TRUE', 'FALSE', 'NULL'):
            val = True if tok.kind == 'TRUE' else (False if tok.kind == 'FALSE' else None)
            self.consume()
            return LiteralNode(val)
        elif tok.kind == 'VAR':
            return VarNode(self.consume().value)
        elif tok.kind == 'IDENT':
            name = self.consume().value
            if self.peek().kind == '(':
                self.consume('(')
                args = []
                if self.peek().kind != ')':
                    args.append(self.parse_comma())
                    while self.peek().kind == ';':
                        self.consume(';')
                        args.append(self.parse_comma())
                self.consume(')')
                return FuncCallNode(name, args)
            else:
                return FuncCallNode(name, [])
        elif tok.kind == '(':
            self.consume('(')
            node = self.parse_comma()
            self.consume(')')
            return node
        elif tok.kind == '[':
            self.consume('[')
            elems = []
            if self.peek().kind != ']':
                elems.append(self.parse_comma())
            self.consume(']')
            return ListNode(elems)
        elif tok.kind == '{':
            self.consume('{')
            entries = []
            while self.peek().kind != '}':
                if self.peek().kind == 'STRING':
                    k = LiteralNode(self.consume().value)
                elif self.peek().kind == 'IDENT':
                    k = LiteralNode(self.consume().value)
                else:
                    k = self.parse_primary()
                self.consume(':')
                v = self.parse_pipe()
                entries.append((k, v))
                if self.peek().kind == ',':
                    self.consume(',')
            self.consume('}')
            return MapNode(entries)
        else:
            raise SyntaxError(f"Unexpected token {tok.kind} ({tok.value})")

