                    cur_item = [idx]
                else:
                    cur_item.append(idx)
            if cur_item:
                result.append(parse_item(cur_item))
            return result
        else:
            result = {}
            cur_key = None
            cur_val_lines = []
            for idx in line_indices:
                line = lines[idx]
                if not line.strip(): continue
                cur_ind = get_indent(line)
                if cur_ind == indent and ':' in line.lstrip():
                    if cur_key is not None:
                        result[cur_key] = parse_val(cur_val_lines)
                    k, _, v = line.lstrip().partition(':')
                    cur_key = parse_scalar(k.strip())
                    v_str = v.strip()
                    if v_str:
                        cur_val_lines = [(idx, v_str)]
                    else:
