                        result[cur_key] = parse_val(cur_val_lines)
                    k, _, v = line.lstrip().partition(':')
                    cur_key = parse_scalar(k.strip())
                    v_str = v.strip()
                    if v_str:
                        cur_val_lines = [(idx, v_str)]
                    else:
                        cur_val_lines = []
                else:
                    cur_val_lines.append(idx)
            if cur_key is not None:
                result[cur_key] = parse_val(cur_val_lines)
            return result

    def parse_item(item_lines):
        first_idx = item_lines[0]
        first_line = lines[first_idx]
        content = first_line.lstrip()
        after = content[1:].lstrip()
        if not after:
            if len(item_lines) > 1:
                return parse_block(item_lines[1:])
            return None
        elif ':' in after and not (after.startswith('{') or after.startswith('[')):
            ind = get_indent(first_line) + 2
            lines[first_idx] = ' ' * ind + after
            return parse_block(item_lines)
        else:
            return parse_scalar(after)

    def parse_val(val_lines):
        if not val_lines: return None
        if isinstance(val_lines[0], tuple):
            v_str = val_lines[0][1]
            rest = val_lines[1:]
            if rest:
                return parse_block(rest)
            return parse_scalar(v_str)
        else:
            return parse_block(val_lines)

    non_empty = [i for i, l in enumerate(lines) if l.strip()]
    if not non_empty: return None
    return parse_block(non_empty)

def parse_yaml_all(text):
    docs = []
    raw_docs = re.split(r'^---\s*$', text, flags=re.MULTILINE)
    for rd in raw_docs:
        if not rd.strip(): continue
        doc = parse_yaml_doc(rd)
        docs.append(doc)
    return docs if docs else [None]

def dump_yaml(val, indent_level=2, compact_seq=False, is_root=True, current_indent=0):
    if val is None:
        return "null"
    if isinstance(val, bool):
        return "true" if val else "false"
    if isinstance(val, (int, float)):
        return str(val)
    if isinstance(val, str):
        if '\n' in val:
            lines = val.splitlines()
            ind_str = " " * (current_indent + indent_level)
            return "|\n" + "\n".join(ind_str + l for l in lines)
        if any(ch in val for ch in (':', '#', '{', '}', '[', ']', ',', '&', '*', '?', '|', '-', '<', '>', '=', '!', '%', '@', '`')):
            return f'"{val}"'
        if val.isdigit() or val.lower() in ('true', 'false', 'null'):
            return f'"{val}"'
        return val
    if isinstance(val, list):
        if not val: return "[]"
        lines = []
        for item in val:
            item_str = dump_yaml(item, indent_level, compact_seq, is_root=False, current_indent=current_indent + indent_level)
            if isinstance(item, (dict, list)) and item_str.startswith("\n"):
                prefix = "-"
                lines.append(f"{prefix}{item_str}")
            elif isinstance(item, dict):
                dict_lines = item_str.splitlines()
                first = dict_lines[0]
                rest = dict_lines[1:]
                lines.append(f"- {first}")
                for r in rest:
                    lines.append(f"  {r}")
            else:
                lines.append(f"- {item_str}")
        ind = " " * current_indent
        return "\n".join(ind + l for l in lines)
    if isinstance(val, dict):
        if not val: return "{}"
        lines = []
        for k, v in val.items():
            k_str = dump_yaml(k, indent_level, compact_seq, is_root=False, current_indent=0)
            v_str = dump_yaml(v, indent_level, compact_seq, is_root=False, current_indent=current_indent + indent_level)
            if isinstance(v, dict):
                lines.append(f"{k_str}:\n" + "\n".join(" " * indent_level + l for l in v_str.splitlines()))
            elif isinstance(v, list):
                if compact_seq:
                    lines.append(f"{k_str}:\n" + v_str)
                else:
                    lines.append(f"{k_str}:\n" + "\n".join(" " * indent_level + l for l in v_str.splitlines()))
            else:
                lines.append(f"{k_str}: {v_str}")
        return "\n".join(lines)
    return str(val)

# -------------------------------------------------------------
# Expression Tokenizer, Parser, AST & Evaluator
# -------------------------------------------------------------
class Token:
    def __init__(self, kind, value, pos=0):
        self.kind = kind; self.value = value; self.pos = pos

def tokenize(s):
    tokens = []
    i = 0; n = len(s)
    while i < n:
        ch = s[i]
        if ch.isspace():
            i += 1; continue
        if ch in ('"', "'"):
            quote = ch; j = i + 1; val = []
            while j < n and s[j] != quote:
                if s[j] == '\\' and j + 1 < n:
                    val.append(s[j+1]); j += 2
                else:
                    val.append(s[j]); j += 1
            if j < n: j += 1
            tokens.append(Token('STRING', ''.join(val), i))
            i = j; continue
        if i + 1 < n:
            two = s[i:i+2]
            if two in ('==', '!=', '<=', '>=', '+=', '-=', '*=', '|=', '..'):
                tokens.append(Token(two, two, i))
                i += 2; continue
        if ch in ('.', ',', '|', '=', '<', '>', '+', '-', '*', '/', '%', ':', '(', ')', '[', ']', '{', '}', ';'):
            tokens.append(Token(ch, ch, i))
            i += 1; continue
        if ch == '$':
            j = i + 1
            while j < n and (s[j].isalnum() or s[j] == '_'): j += 1
            tokens.append(Token('VAR', s[i:j], i))
            i = j; continue
        if ch.isdigit():
            j = i
            while j < n and (s[j].isdigit() or s[j] == '.'): j += 1
            num_str = s[i:j]
            val = float(num_str) if '.' in num_str else int(num_str)
            tokens.append(Token('NUMBER', val, i))
            i = j; continue
        if ch.isalpha() or ch == '_':
            j = i
            while j < n and (s[j].isalnum() or s[j] in ('_', '-')): j += 1
            word = s[i:j]
            if word in ('and', 'or', 'not', 'as', 'true', 'false', 'null'):
                tokens.append(Token(word.upper(), word, i))
            else:
                tokens.append(Token('IDENT', word, i))
            i = j; continue
        tokens.append(Token('CHAR', ch, i))
        i += 1
    tokens.append(Token('EOF', '', n))
    return tokens

class ExprParser:
    def __init__(self, tokens):
        self.tokens = tokens; self.pos = 0

    def peek(self): return self.tokens[self.pos]

    def consume(self, kind=None):
        tok = self.peek()
        if kind and tok.kind != kind and tok.value != kind:
            raise SyntaxError(f"Expected {kind}, got {tok.kind} ({tok.value})")
        self.pos += 1
        return tok

    def parse(self):
        if self.peek().kind == 'EOF': return DotNode()
        return self.parse_comma()

    def parse_comma(self):
        node = self.parse_pipe()
        while self.peek().kind == ',':
            self.consume(',')
            right = self.parse_pipe()
            node = CommaNode(node, right)
        return node

    def parse_pipe(self):
        node = self.parse_assign()
        while self.peek().kind == '|':
            self.consume('|')
            right = self.parse_assign()
            node = PipeNode(node, right)
        return node

    def parse_assign(self):
        node = self.parse_as()
        tok = self.peek()
        if tok.kind in ('=', '+=', '-=', '*=', '|='):
            op = tok.kind
            self.consume()
            right = self.parse_assign()
            return AssignNode(node, op, right)
        return node

    def parse_as(self):
        node = self.parse_or()
        if self.peek().kind == 'AS':
            self.consume('AS')
            var_tok = self.consume('VAR')
            if self.peek().kind == '|': self.consume('|')
            right = self.parse_pipe()
            return AsNode(node, var_tok.value, right)
        return node

    def parse_or(self):
        node = self.parse_and()
        while self.peek().kind == 'OR':
            self.consume('OR')
            right = self.parse_and()
            node = BinaryOpNode(node, 'or', right)
        return node

    def parse_and(self):
        node = self.parse_eq()
        while self.peek().kind == 'AND':
            self.consume('AND')
            right = self.parse_eq()
            node = BinaryOpNode(node, 'and', right)
        return node

    def parse_eq(self):
        node = self.parse_rel()
        while self.peek().kind in ('==', '!='):
            op = self.consume().kind
            right = self.parse_rel()
            node = BinaryOpNode(node, op, right)
        return node

    def parse_rel(self):
        node = self.parse_add()
        while self.peek().kind in ('<', '>', '<=', '>='):
            op = self.consume().kind
            right = self.parse_add()
            node = BinaryOpNode(node, op, right)
        return node

    def parse_add(self):
        node = self.parse_mul()
        while self.peek().kind in ('+', '-'):
            op = self.consume().kind
            right = self.parse_mul()
            node = BinaryOpNode(node, op, right)
        return node

    def parse_mul(self):
        node = self.parse_postfix()
        while self.peek().kind in ('*', '/', '%'):
            op = self.consume().kind
            right = self.parse_postfix()
            node = BinaryOpNode(node, op, right)
        return node

    def parse_postfix(self):
        node = self.parse_primary()
        while True:
            tok = self.peek()
            if tok.kind == '.':
                self.consume('.')
                next_tok = self.peek()
                if next_tok.kind in ('IDENT', 'STRING'):
                    key = self.consume().value
                    node = PathAccessNode(node, key)
                elif next_tok.kind == '[':
                    pass
                else:
                    break
            elif tok.kind == '[':
                self.consume('[')
                if self.peek().kind == ']':
                    self.consume(']')
                    node = ArrayIterNode(node)
                else:
                    idx_expr = self.parse_comma()
                    self.consume(']')
                    node = ArrayIndexNode(node, idx_expr)
            else:
                break
        return node

    def parse_primary(self):
        tok = self.peek()
        if tok.kind == '.':
            self.consume('.')
            next_tok = self.peek()
            if next_tok.kind in ('IDENT', 'STRING'):
                key = self.consume().value
                return PathAccessNode(DotNode(), key)
            elif next_tok.kind == '[':
                self.consume('[')
                if self.peek().kind == ']':
                    self.consume(']')
                    return ArrayIterNode(DotNode())
                else:
                    idx_expr = self.parse_comma()
                    self.consume(']')
                    return ArrayIndexNode(DotNode(), idx_expr)
            else:
                return DotNode()
        elif tok.kind == 'NUMBER': return LiteralNode(self.consume().value)
        elif tok.kind == 'STRING': return LiteralNode(self.consume().value)
        elif tok.kind in ('TRUE', 'FALSE', 'NULL'):
            val = True if tok.kind == 'TRUE' else (False if tok.kind == 'FALSE' else None)
            self.consume(); return LiteralNode(val)
        elif tok.kind == 'VAR': return VarNode(self.consume().value)
        elif tok.kind == 'IDENT':
            name = self.consume().value
            if self.peek().kind == '(':
                self.consume('(')
                args = []
                if self.peek().kind != ')':
                    args.append(self.parse_comma())
                    while self.peek().kind == ';':
                        self.consume(';')
                        args.append(self.parse_comma())
                self.consume(')')
                return FuncCallNode(name, args)
            else:
                return FuncCallNode(name, [])
        elif tok.kind == '(':
            self.consume('(')
            node = self.parse_comma()
            self.consume(')')
            return node
        elif tok.kind == '[':
            self.consume('[')
            elems = []
            if self.peek().kind != ']':
                elems.append(self.parse_comma())
            self.consume(']')
            return ListNode(elems)
        elif tok.kind == '{':
            self.consume('{')
            entries = []
            while self.peek().kind != '}':
                if self.peek().kind in ('STRING', 'IDENT'):
                    k = LiteralNode(self.consume().value)
                else:
                    k = self.parse_primary()
                self.consume(':')
                v = self.parse_pipe()
                entries.append((k, v))
                if self.peek().kind == ',': self.consume(',')
            self.consume('}')
            return MapNode(entries)
        else:
            raise SyntaxError(f"Unexpected token {tok.kind} ({tok.value})")

class DotNode:
    def eval(self, val, ctx): return [val]

class LiteralNode:
    def __init__(self, val): self.val = val
    def eval(self, val, ctx): return [self.val]

class VarNode:
    def __init__(self, name): self.name = name
    def eval(self, val, ctx): return [ctx.get('vars', {}).get(self.name)]

class PathAccessNode:
    def __init__(self, parent, key): self.parent = parent; self.key = key
    def eval(self, val, ctx):
        p_vals = self.parent.eval(val, ctx)
        res = []
        for pv in p_vals:
            if isinstance(pv, dict): res.append(pv.get(self.key))
            else: res.append(None)
        return res

class ArrayIterNode:
    def __init__(self, parent): self.parent = parent
    def eval(self, val, ctx):
        p_vals = self.parent.eval(val, ctx)
        res = []
        for pv in p_vals:
            if isinstance(pv, list): res.extend(pv)
            elif isinstance(pv, dict): res.extend(pv.values())
        return res

class ArrayIndexNode:
    def __init__(self, parent, idx_expr): self.parent = parent; self.idx_expr = idx_expr
    def eval(self, val, ctx):
        p_vals = self.parent.eval(val, ctx)
        res = []
        for pv in p_vals:
            idxs = self.idx_expr.eval(val, ctx)
            for idx in idxs:
                if isinstance(pv, list) and isinstance(idx, int):
                    if -len(pv) <= idx < len(pv): res.append(pv[idx])
                    else: res.append(None)
                else: res.append(None)
        return res

class PipeNode:
    def __init__(self, left, right): self.left = left; self.right = right
    def eval(self, val, ctx):
        l_vals = self.left.eval(val, ctx)
        res = []
        for lv in l_vals:
            res.extend(self.right.eval(lv, ctx))
        return res

class CommaNode:
    def __init__(self, left, right): self.left = left; self.right = right
    def eval(self, val, ctx):
        return self.left.eval(val, ctx) + self.right.eval(val, ctx)

class BinaryOpNode:
    def __init__(self, left, op, right): self.left = left; self.op = op; self.right = right
    def eval(self, val, ctx):
        l_vals = self.left.eval(val, ctx)
        r_vals = self.right.eval(val, ctx)
        res = []
        for lv in l_vals:
            for rv in r_vals:
                if self.op == '+':
                    if isinstance(lv, list) and isinstance(rv, list): res.append(lv + rv)
                    elif isinstance(lv, dict) and isinstance(rv, dict):
                        d = dict(lv); d.update(rv); res.append(d)
                    elif isinstance(lv, (int, float)) and isinstance(rv, (int, float)): res.append(lv + rv)
                    elif isinstance(lv, str) and isinstance(rv, str): res.append(lv + rv)
                    else: res.append(None)
                elif self.op == '*':
                    if isinstance(lv, dict) and isinstance(rv, dict):
                        def deep_merge(a, b):
                            res_m = dict(a)
                            for k, v in b.items():
                                if k in res_m and isinstance(res_m[k], dict) and isinstance(v, dict):
                                    res_m[k] = deep_merge(res_m[k], v)
                                else: res_m[k] = v
                            return res_m
                        res.append(deep_merge(lv, rv))
                    elif isinstance(lv, (int, float)) and isinstance(rv, (int, float)): res.append(lv * rv)
                    else: res.append(None)
                elif self.op == '==': res.append(lv == rv)
                elif self.op == '!=': res.append(lv != rv)
                elif self.op == '<': res.append(lv < rv if lv is not None and rv is not None else False)
                elif self.op == '>': res.append(lv > rv if lv is not None and rv is not None else False)
                elif self.op == '<=': res.append(lv <= rv if lv is not None and rv is not None else False)
                elif self.op == '>=': res.append(lv >= rv if lv is not None and rv is not None else False)
                elif self.op == 'and': res.append(bool(lv and rv))
                elif self.op == 'or': res.append(bool(lv or rv))
        return res

class AsNode:
    def __init__(self, left, var_name, right): self.left = left; self.var_name = var_name; self.right = right
    def eval(self, val, ctx):
        l_vals = self.left.eval(val, ctx)
        res = []
        for lv in l_vals:
            new_ctx = dict(ctx)
            vars_dict = dict(ctx.get('vars', {}))
            vars_dict[self.var_name] = lv
            new_ctx['vars'] = vars_dict
            res.extend(self.right.eval(val, new_ctx))
        return res

class FuncCallNode:
    def __init__(self, name, args): self.name = name; self.args = args
    def eval(self, val, ctx):
        if self.name == 'select':
            if self.args:
                cond_vals = self.args[0].eval(val, ctx)
                if any(c not in (False, None) for c in cond_vals): return [val]
            return []
        elif self.name == 'del':
            if self.args and isinstance(self.args[0], PathAccessNode):
                p_node = self.args[0]
                key = p_node.key
                p_val = p_node.parent.eval(val, ctx)[0]
                if isinstance(p_val, dict) and key in p_val:
                    del p_val[key]
                elif isinstance(p_val, list) and isinstance(key, int):
                    if -len(p_val) <= key < len(p_val):
                        del p_val[key]
            return [val]
        elif self.name == 'keys':
            if isinstance(val, dict): return [list(val.keys())]
            return []
        elif self.name == 'length':
            if isinstance(val, (dict, list, str)): return [len(val)]
            return [0]
        elif self.name == 'has':
            if self.args and isinstance(val, dict):
                k = self.args[0].eval(val, ctx)[0]
                return [k in val]
            return [False]
        elif self.name == 'type':
            if isinstance(val, dict): return ['!!map']
            if isinstance(val, list): return ['!!seq']
            if isinstance(val, str): return ['!!str']
            if isinstance(val, int): return ['!!int']
            if isinstance(val, float): return ['!!float']
            if isinstance(val, bool): return ['!!bool']
            return ['!!null']
        elif self.name == 'strenv':
            if self.args:
                vname = self.args[0].eval(val, ctx)[0]
                return [str(os.environ.get(str(vname), ''))]
            return ['']
        elif self.name == 'env':
            if self.args:
                vname = self.args[0].eval(val, ctx)[0]
                raw = os.environ.get(str(vname), '')
                if raw.isdigit(): return [int(raw)]
                if raw.lower() == 'true': return [True]
                if raw.lower() == 'false': return [False]
                return [raw]
            return ['']
        elif self.name == 'not':
            return [not bool(val)]
        elif self.name == 'filename':
            return [ctx.get('filename', '')]
        elif self.name in ('fileIndex', 'fi'):
            return [ctx.get('fileIndex', 0)]
        elif self.name in ('documentIndex', 'di'):
            return [ctx.get('documentIndex', 0)]
        return [val]

class AssignNode:
    def __init__(self, path_ast, op, val_ast): self.path_ast = path_ast; self.op = op; self.val_ast = val_ast
    def eval(self, val, ctx):
        if val is None:
            val = {}
        r_vals = self.val_ast.eval(val, ctx)
        r_val = r_vals[0] if r_vals else None
        if isinstance(self.path_ast, PathAccessNode):
            key = self.path_ast.key
            p_vals = self.path_ast.parent.eval(val, ctx)
            p_val = p_vals[0] if p_vals else None
            if p_val is None:
                p_val = {}
                if isinstance(self.path_ast.parent, PathAccessNode):
                    p_key = self.path_ast.parent.key
                    val[p_key] = p_val
                elif isinstance(self.path_ast.parent, DotNode):
                    val = p_val
            if isinstance(p_val, dict):
                if self.op == '=': p_val[key] = r_val
                elif self.op == '+=': p_val[key] = p_val.get(key, 0) + r_val
                elif self.op == '*=': p_val[key] = p_val.get(key, {}) * r_val
        return [val]

class ListNode:
    def __init__(self, elems): self.elems = elems
    def eval(self, val, ctx):
        res = []
        for e in self.elems: res.extend(e.eval(val, ctx))
        return [res]

class MapNode:
    def __init__(self, entries): self.entries = entries
    def eval(self, val, ctx):
        res = {}
        for k_ast, v_ast in self.entries:
            k_val = k_ast.eval(val, ctx)[0]
            v_val = v_ast.eval(val, ctx)[0]
            res[k_val] = v_val
        return [res]

def eval_yq(expr_str, data, ctx=None):
    if ctx is None: ctx = {}
    tokens = tokenize(expr_str)
    parser = ExprParser(tokens)
    ast = parser.parse()
    return ast.eval(data, ctx)

# -------------------------------------------------------------
# CLI Parser & Main Entry
# -------------------------------------------------------------
def main():
    args = sys.argv[1:]

    if not args:
        if not sys.stdin.isatty():
            data_str = sys.stdin.read()
            docs = parse_yaml_all(data_str)
            for i, doc in enumerate(docs):
                if i > 0: sys.stdout.write("---\n")
                out = dump_yaml(doc)
                sys.stdout.write(out + "\n")
            sys.exit(0)
        else:
            sys.stdout.write(MAIN_HELP)
            sys.exit(0)

    if args[0] in ("-V", "--version"):
        sys.stdout.write(VERSION + "\n")
        sys.exit(0)

    if args[0] in ("-h", "--help"):
        sys.stdout.write(MAIN_HELP)
        sys.exit(0)

    if args[0] == "help":
        if len(args) > 1 and args[1] in ("eval", "e"): sys.stdout.write(EVAL_HELP)
        elif len(args) > 1 and args[1] in ("eval-all", "ea"): sys.stdout.write(EVAL_ALL_HELP)
        elif len(args) > 1 and args[1] in ("completion", "shell-completion"): sys.stdout.write(COMPLETION_HELP)
        else: sys.stdout.write(MAIN_HELP)
        sys.exit(0)

    subcmd = "eval"
    if args[0] in ("eval", "e"):
        subcmd = "eval"; args = args[1:]
    elif args[0] in ("eval-all", "ea"):
        subcmd = "eval-all"; args = args[1:]
    elif args[0] in ("completion", "shell-completion"):
        args = args[1:]
        shell = "bash"
        if args and not args[0].startswith("-"):
            shell = args[0]; args = args[1:]
        if "-h" in args or "--help" in args:
            sys.stdout.write(COMPLETION_HELP); sys.exit(0)
        sys.stdout.write(COMP_SCRIPTS.get(shell, COMP_SCRIPTS["bash"]))
        sys.exit(0)

    flags = {
        'input_format': 'auto', 'output_format': 'auto', 'inplace': False,
        'null_input': False, 'no_doc': False, 'nul_output': False,
        'unwrap_scalar': True, 'compact_seq': False, 'exit_status': False,
        'indent': 2, 'pretty_print': False, 'from_file': None,
        'expression': None, 'split_exp': None, 'front_matter': None,
    }

    pos_args = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-V", "--version"):
            sys.stdout.write(VERSION + "\n"); sys.exit(0)
        elif a in ("-h", "--help"):
            if subcmd == "eval": sys.stdout.write(EVAL_HELP)
            elif subcmd == "eval-all": sys.stdout.write(EVAL_ALL_HELP)
            else: sys.stdout.write(MAIN_HELP)
            sys.exit(0)
        elif a in ("-n", "--null-input"): flags['null_input'] = True
        elif a in ("-i", "--inplace"): flags['inplace'] = True
