    def parse_item(item_lines):
        first_idx = item_lines[0]
        first_line = lines[first_idx]
        content = first_line.lstrip()
        after = content[1:].lstrip()
        if not after:
            if len(item_lines) > 1:
                return parse_block(item_lines[1:])
            return None
        elif ':' in after and not (after.startswith('{') or after.startswith('[')):
            ind = get_indent(first_line) + 2
