def dump_yaml(val, indent_level=2, compact_seq=False, is_root=True, current_indent=0):
    if val is None:
        return "null"
    if isinstance(val, bool):
        return "true" if val else "false"
    if isinstance(val, (int, float)):
        return str(val)
    if isinstance(val, str):
        if '\n' in val:
            lines = val.splitlines()
            ind_str = " " * (current_indent + indent_level)
            return "|\n" + "\n".join(ind_str + l for l in lines)
        if any(ch in val for ch in (':', '#', '{', '}', '[', ']', ',', '&', '*', '?', '|', '-', '<', '>', '=', '!', '%', '@', '`')):
            return f'"{val}"'
        if val.isdigit() or val.lower() in ('true', 'false', 'null'):
            return f'"{val}"'
        return val
    if isinstance(val, list):
        if not val: return "[]"
        lines = []
        for item in val:
            item_str = dump_yaml(item, indent_level, compact_seq, is_root=False, current_indent=current_indent + indent_level)
            if isinstance(item, (dict, list)) and item_str.startswith("\n"):
                prefix = "-"
                lines.append(f"{prefix}{item_str}")
            elif isinstance(item, dict):
                dict_lines = item_str.splitlines()
                first = dict_lines[0]
                rest = dict_lines[1:]
                lines.append(f"- {first}")
                for r in rest:
                    lines.append(f"  {r}")
            else:
                lines.append(f"- {item_str}")
        ind = " " * current_indent
        return "\n".join(ind + l for l in lines)
    if isinstance(val, dict):
        if not val: return "{}"
        lines = []
        for k, v in val.items():
            k_str = dump_yaml(k, indent_level, compact_seq, is_root=False, current_indent=0)
            v_str = dump_yaml(v, indent_level, compact_seq, is_root=False, current_indent=current_indent + indent_level)
            if isinstance(v, dict):
                lines.append(f"{k_str}:\n" + "\n".join(" " * indent_level + l for l in v_str.splitlines()))
            elif isinstance(v, list):
                if compact_seq:
                    lines.append(f"{k_str}:\n" + v_str)
                else:
                    lines.append(f"{k_str}:\n" + "\n".join(" " * indent_level + l for l in v_str.splitlines()))
            else:
                lines.append(f"{k_str}: {v_str}")
        return "\n".join(lines)
    return str(val)

