def main():
    args = sys.argv[1:]

    if not args:
        if not sys.stdin.isatty():
            data_str = sys.stdin.read()
            docs = parse_yaml_all(data_str)
            for i, doc in enumerate(docs):
                if i > 0: sys.stdout.write("---\n")
                out = dump_yaml(doc)
                sys.stdout.write(out + "\n")
            sys.exit(0)
        else:
            sys.stdout.write(MAIN_HELP)
            sys.exit(0)

    if args[0] in ("-V", "--version"):
        sys.stdout.write(VERSION + "\n")
        sys.exit(0)

    if args[0] in ("-h", "--help"):
        sys.stdout.write(MAIN_HELP)
        sys.exit(0)

    if args[0] == "help":
        if len(args) > 1 and args[1] in ("eval", "e"): sys.stdout.write(EVAL_HELP)
        elif len(args) > 1 and args[1] in ("eval-all", "ea"): sys.stdout.write(EVAL_ALL_HELP)
        elif len(args) > 1 and args[1] in ("completion", "shell-completion"): sys.stdout.write(COMPLETION_HELP)
        else: sys.stdout.write(MAIN_HELP)
        sys.exit(0)

    subcmd = "eval"
    if args[0] in ("eval", "e"):
        subcmd = "eval"; args = args[1:]
    elif args[0] in ("eval-all", "ea"):
        subcmd = "eval-all"; args = args[1:]
    elif args[0] in ("completion", "shell-completion"):
        args = args[1:]
        shell = "bash"
        if args and not args[0].startswith("-"):
            shell = args[0]; args = args[1:]
        if "-h" in args or "--help" in args:
            sys.stdout.write(COMPLETION_HELP); sys.exit(0)
        sys.stdout.write(COMP_SCRIPTS.get(shell, COMP_SCRIPTS["bash"]))
        sys.exit(0)

    flags = {
        'input_format': 'auto', 'output_format': 'auto', 'inplace': False,
        'null_input': False, 'no_doc': False, 'nul_output': False,
        'unwrap_scalar': True, 'compact_seq': False, 'exit_status': False,
        'indent': 2, 'pretty_print': False, 'from_file': None,
        'expression': None, 'split_exp': None, 'front_matter': None,
    }

    pos_args = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-V", "--version"):
            sys.stdout.write(VERSION + "\n"); sys.exit(0)
        elif a in ("-h", "--help"):
            if subcmd == "eval": sys.stdout.write(EVAL_HELP)
            elif subcmd == "eval-all": sys.stdout.write(EVAL_ALL_HELP)
            else: sys.stdout.write(MAIN_HELP)
            sys.exit(0)
        elif a in ("-n", "--null-input"): flags['null_input'] = True
        elif a in ("-i", "--inplace"): flags['inplace'] = True
        elif a in ("-N", "--no-doc"): flags['no_doc'] = True
        elif a in ("-0", "--nul-output"): flags['nul_output'] = True
        elif a in ("-e", "--exit-status"): flags['exit_status'] = True
        elif a in ("-c", "--yaml-compact-seq-indent"): flags['compact_seq'] = True
        elif a in ("-P", "--prettyPrint"): flags['pretty_print'] = True
        elif a in ("-r", "--unwrapScalar"): flags['unwrap_scalar'] = True
        elif a.startswith("-r="): flags['unwrap_scalar'] = (a.split("=", 1)[1].lower() == "true")
        elif a.startswith("--unwrapScalar="): flags['unwrap_scalar'] = (a.split("=", 1)[1].lower() == "true")
        elif a in ("-I", "--indent"):
            i += 1; flags['indent'] = int(args[i])
        elif a.startswith("-I"): flags['indent'] = int(a[2:])
        elif a in ("-p", "--input-format"):
            i += 1; flags['input_format'] = args[i]
        elif a.startswith("-p"): flags['input_format'] = a[2:]
        elif a.startswith("--input-format="): flags['input_format'] = a.split("=", 1)[1]
        elif a in ("-o", "--output-format"):
            i += 1; flags['output_format'] = args[i]
        elif a.startswith("-o"): flags['output_format'] = a[2:]
        elif a.startswith("--output-format="): flags['output_format'] = a.split("=", 1)[1]
        elif a in ("-s", "--split-exp"):
            i += 1; flags['split_exp'] = args[i]
        elif a in ("-f", "--front-matter"):
            i += 1; flags['front_matter'] = args[i]
        elif a == "--from-file":
            i += 1; flags['from_file'] = args[i]
        elif a == "--expression":
            i += 1; flags['expression'] = args[i]
        elif a.startswith("-"):
            if a.startswith("--"):
                sys.stderr.write(f"Error: unknown flag: {a}\nUsage:\n  yq [flags]\n  yq [command]\n")
                sys.exit(1)
            else:
                j = 1
                while j < len(a):
                    ch = a[j]
                    if ch == 'n': flags['null_input'] = True
                    elif ch == 'i': flags['inplace'] = True
                    elif ch == 'N': flags['no_doc'] = True
                    elif ch == '0': flags['nul_output'] = True
                    elif ch == 'e': flags['exit_status'] = True
                    elif ch == 'c': flags['compact_seq'] = True
                    elif ch == 'P': flags['pretty_print'] = True
                    elif ch == 'r': flags['unwrap_scalar'] = True
                    elif ch == 'o':
                        flags['output_format'] = a[j+1:]; break
                    elif ch == 'p':
                        flags['input_format'] = a[j+1:]; break
                    elif ch == 'I':
                        flags['indent'] = int(a[j+1:]); break
                    j += 1
        else:
            pos_args.append(a)
        i += 1

    expr_str = "."
    files = []

    if flags['from_file']:
        with open(flags['from_file']) as ff: expr_str = ff.read().strip()
        files = pos_args
    elif flags['expression']:
        expr_str = flags['expression']
        files = pos_args
    elif pos_args:
        if len(pos_args) == 1 and os.path.exists(pos_args[0]):
            expr_str = "."
            files = pos_args
        else:
            expr_str = pos_args[0]
            files = pos_args[1:]

    inputs = []
    if flags['null_input']:
        inputs.append(("", 0, 0, None))
    elif files:
        for fi, fname in enumerate(files):
            if fname == "-":
                raw = sys.stdin.read()
                docs = parse_yaml_all(raw)
                for di, d in enumerate(docs): inputs.append(("-", fi, di, d))
            else:
                if not os.path.exists(fname):
                    sys.stderr.write(f"Error: open {fname}: no such file or directory\n")
                    sys.exit(1)
                with open(fname) as f: raw = f.read()
                docs = parse_yaml_all(raw)
                for di, d in enumerate(docs): inputs.append((fname, fi, di, d))
    else:
        raw = sys.stdin.read()
        docs = parse_yaml_all(raw)
        for di, d in enumerate(docs): inputs.append(("-", 0, di, d))

    results = []
    for fname, fi, di, doc in inputs:
        ctx = {'filename': fname, 'fileIndex': fi, 'documentIndex': di, 'vars': {}}
        try:
            eval_res = eval_yq(expr_str, doc, ctx)
            results.extend(eval_res)
        except Exception as ex:
            sys.stderr.write(f"Error: {ex}\n")
            sys.exit(1)

    out_format = flags['output_format']
    if out_format in ("auto", "a"): out_format = "yaml"
    if out_format in ("y", "kyaml", "ky"): out_format = "yaml"
    if out_format in ("j",): out_format = "json"

    matched = False
    for idx, res in enumerate(results):
        if res is not None and res is not False:
            matched = True

        if out_format == "json":
            out_str = json.dumps(res, indent=flags['indent'])
        else:
            if isinstance(res, (str, int, float, bool)) and flags['unwrap_scalar']:
                out_str = str(res) if res is not None else "null"
            else:
                out_str = dump_yaml(res, indent_level=flags['indent'], compact_seq=flags['compact_seq'])

        if idx > 0 and not flags['no_doc'] and out_format == "yaml":
            sys.stdout.write("---\n")

        sep = "\0" if flags['nul_output'] else "\n"
        sys.stdout.write(out_str + sep)

    if flags['exit_status'] and not matched:
        sys.stderr.write("Error: no matches found\n")
        sys.exit(1)

